HOME=C.parent
def display_path(value):
    path=Path(value)
    if not path.is_absolute():
        return str(path)
    for root,label in ((C,''),(HOME/'opl-instance-medopl','../opl-instance-medopl')):
        try:
            rel=path.relative_to(root)
        except ValueError:
            continue
        return str(Path(label)/rel) if label else str(rel)
    return str(path)
